# hypothesis: In a diamond hierarchy, Self-typed fluent methods and the classmethod constructor return the receiver's most-derived class, so Bottom chains stay typed as Bottom even though the methods are defined on Base, Left and Right.
from typing import Self, assert_type, reveal_type


class Base:
    def __init__(self) -> None:
        self.tags: list[str] = []

    def tag(self, name: str) -> Self:
        self.tags.append(name)
        return self

    @classmethod
    def build(cls) -> Self:
        return cls()


class Left(Base):
    def left_only(self) -> Self:
        self.tags.append('L')
        return self


class Right(Base):
    def right_only(self) -> Self:
        self.tags.append('R')
        return self


class Bottom(Left, Right):
    @property
    def count(self) -> int:
        return len(self.tags)

    def finish(self) -> Self:
        return self.tag('end')


def wrong() -> Bottom:
    return Left.build()  # expect-error: Left is not a subtype of Bottom


b = Bottom.build()
assert_type(b, Bottom)
chained = b.tag('a').left_only().right_only().finish()
assert_type(chained, Bottom)
reveal_type(chained.count)
print(chained.count, chained.tags)
print(type(wrong()).__name__)
